op
let p_q = -i(VDD) * 1.8
print p_q

* 2. Transient Analysis: Step response from 100 mV to 900 mV (Fig. 24.31)
tran 0.1n 600n 480n
meas tran v_out_high find v(Vout) at=540n
meas tran v_out_low find v(Vout) at=590n
meas tran v_in_high find v(Vin) at=540n
meas tran v_in_low find v(Vin) at=590n

let a_cl = (v_out_low - v_out_high) / (v_in_high - v_in_low)
print a_cl

* Measure Slew Rates
meas tran sr_pos trig v(Vout) val=0.2 rise=1 targ v(Vout) val=0.8 rise=1
meas tran sr_neg trig v(Vout) val=0.8 fall=1 targ v(Vout) val=0.2 fall=1
let slew_pos = 0.6 / (sr_pos * 1e6)
let slew_neg = 0.6 / (sr_neg * 1e6)
print slew_pos slew_neg

* 3. AC Analysis (Middlebrook / feedback loop evaluation)
* Temporarily configure for open-loop AC
alter R1 = 1e12
alter R2 = 1e12
alter Vin_ac acmag = 1
ac dec 50 1 1G

let gain_db = vdb(Vout)
let phase_deg = 180 + (180/PI * cph(v(Vout)))

meas ac a_oldc find gain_db at=10
meas ac f_un when gain_db=0 fall=1
meas ac p_m find phase_deg when gain_db=0 fall=1

print a_oldc f_un p_m
quit
.endc
.end

